<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {api,ApiError,uncertainMessage} from '../api'
import {operationStatus} from '../nativeStatus'
const props=withDefaults(defineProps<{uid?:number}>(),{uid:0})
const emit=defineEmits(['reauth','expired','action','inspect','compensate'])
const categories:Record<string,string>={reward:'奖励／余额',mail:'邮件',unlock:'装备解锁',stuck:'角色异常',account:'账号问题',other:'其他'}
const statuses:Record<string,string>={open:'待处理',in_progress:'处理中',resolved:'已解决'}
const kinds:Record<string,string>={'case-create':'建立问题','case-update':'更新问题','case-comment':'处理记录','case-link':'关联原操作'}
const busy=ref(false),error=ref(''),notice=ref(''),fields=ref<Record<string,string>>({}),pending=ref(''),receipt=ref<any>(null)
const uidInput=ref(props.uid?String(props.uid):''),scopeUid=ref(props.uid),status=ref(''),category=ref(''),query=ref(''),page=ref(1),more=ref(false),rows=ref<any[]>([])
const profile=ref<any>(null),notes=ref(''),tags=ref(''),creating=ref(false),title=ref(''),description=ref(''),newCategory=ref('other'),role=ref('')
const current=ref<any>(null),eventPage=ref(1),linkPage=ref(1),edit=ref({title:'',description:'',category:'other',status:'open',note:''}),entry=ref(''),linkId=ref(''),relation=ref('reference'),linkNote=ref('')
const feedbackScope=ref('read'),editRevision=ref(0),editBaseline=ref('')
const editDirty=computed(()=>!!current.value&&(JSON.stringify(edit.value)!==editBaseline.value))
const detailDirty=computed(()=>editDirty.value||!!entry.value||!!linkId.value||!!linkNote.value)
function resetEdit(){if(current.value){const c=current.value.case;edit.value={title:c.title,description:c.description,category:c.category,status:c.status,note:''};editRevision.value=c.revision;editBaseline.value=JSON.stringify(edit.value)}}
function discardDetail(){resetEdit();entry.value='';linkId.value='';linkNote.value='';fields.value={};if(['read','edit','entry','link'].includes(feedbackScope.value))error.value=''}
function canLeaveDetail(){if(!detailDirty.value)return true;feedbackScope.value='read';error.value='当前问题还有未保存的修改或处理记录，请先保存，或放弃当前问题草稿';return false}
function canNavigate(){
 if(!canLeaveDetail())return false
 if(profileDirty.value||title.value||description.value||role.value){feedbackScope.value='read';error.value='还有未保存的账号备注或新问题草稿，请先保存或放弃修改再离开工作台';return false}
 return true
}
defineExpose({canNavigate})
const profileDirty=computed(()=>!!profile.value&&(notes.value!==profile.value.notes||tags.value!==profile.value.tags.join('，')))
function discardProfile(){if(profile.value){notes.value=profile.value.notes;tags.value=profile.value.tags.join('，');if(['read','profile'].includes(feedbackScope.value))error.value=''}}
const storage='dnfgm-support-request',locked=computed(()=>busy.value||!!pending.value)
let alive=true
function fail(e:unknown){error.value=uncertainMessage(e);if(e instanceof ApiError&&e.status===401)emit('expired');if(e instanceof ApiError&&e.status===403&&e.message.includes('重新认证'))emit('reauth')}
function remember(id:string){pending.value=id;try{if(id)sessionStorage.setItem(storage,id);else sessionStorage.removeItem(storage)}catch{}}
function time(v:number){return new Date(v*1000).toLocaleString('zh-CN',{hour12:false})}
function integer(text:string,allowEmpty=false){if(allowEmpty&&!text.trim())return 0;const n=Number(text);return /^\d+$/.test(text.trim())&&Number.isInteger(n)&&n>=1&&n<=2147483647?n:null}
function syncDetail(r:any){const preserve=editDirty.value&&current.value?.case.case_id===r.case.case_id;current.value=r;if(!preserve)resetEdit()}
async function loadData(replaceProfile=false){
 const params=new URLSearchParams({uid:String(scopeUid.value),page:String(page.value),status:status.value,category:category.value,q:query.value})
 const list=await api('/support/cases?'+params);if(!alive)return;rows.value=list.items;more.value=list.has_more
 if(scopeUid.value){const p=await api('/support/profiles/'+scopeUid.value);if(!alive)return;if(replaceProfile||!profileDirty.value||profile.value?.uid!==p.uid){profile.value=p;notes.value=p.notes;tags.value=p.tags.join('，')}}else profile.value=null
}
async function search(){if(busy.value)return;fields.value={};const uid=integer(uidInput.value,true);if(uid===null){fields.value.uid='请输入有效账号 UID，留空查看全部';return}if(uid!==scopeUid.value&&profileDirty.value){fields.value.uid='账号备注尚未保存，请先保存或放弃备注修改';return}if(!canLeaveDetail())return;if(title.value||description.value||role.value){fields.value.uid='新问题尚未保存，请先保存或取消新问题';return}scopeUid.value=uid;page.value=1;current.value=null;await load()}
async function load(){if(busy.value)return;feedbackScope.value='read';busy.value=true;error.value='';try{await loadData()}catch(e){if(alive)fail(e)}finally{if(alive)busy.value=false}}
async function detail(cid:string){if(busy.value)return;feedbackScope.value='read';busy.value=true;error.value='';try{const r=await api(`/support/cases/${cid}?event_page=${eventPage.value}&link_page=${linkPage.value}`);if(alive)syncDetail(r)}catch(e){if(alive)fail(e)}finally{if(alive)busy.value=false}}
async function open(row:any){if(busy.value||!canLeaveDetail())return;eventPage.value=1;linkPage.value=1;entry.value='';linkId.value='';linkNote.value='';fields.value={};await detail(row.case_id)}
async function refreshResult(r:any){
 if(r.kind==='case-update'&&current.value?.case.case_id===r.case_id)editBaseline.value=JSON.stringify(edit.value);
 receipt.value=r;notice.value=`管理记录已保存，账号 UID ${r.uid}；未因此发放任何奖励。`;remember('')
 await loadData(r.kind==='player-profile')
 if(r.case_id&&current.value&&current.value.case.case_id!==r.case_id&&detailDirty.value){notice.value+='当前问题草稿已保留；恢复记录属于另一个问题，请按编号另行查看。';return}
 if(r.case_id){eventPage.value=1;linkPage.value=1;const d=await api('/support/cases/'+r.case_id);if(alive)syncDetail(d)}
}
async function mutate(path:string,method:string,body:any){
 if(locked.value)return;feedbackScope.value=path.includes('/profiles/')?'profile':path.endsWith('/entries')?'entry':path.endsWith('/links')?'link':method==='PUT'?'edit':'create';error.value='';notice.value='';busy.value=true;const id=crypto.randomUUID();remember(id)
 let saved=false
 try{const r=await api(path,method,{...body,idempotency_key:id});if(!alive)return;saved=true;await refreshResult(r)}
 catch(e){if(alive){if(!saved&&e instanceof ApiError&&[400,401,403,404,405,409,413,422,429].includes(e.status))remember('');fail(e);if(saved)error.value='保存已提交，但刷新失败：'+error.value}}
 finally{if(alive)busy.value=false}
}
async function recover(){if(busy.value||!pending.value)return;feedbackScope.value='read';busy.value=true;error.value='';try{const r=await api('/support/requests/'+pending.value);if(alive)await refreshResult(r)}catch(e){if(alive)fail(e)}finally{if(alive)busy.value=false}}
async function saveProfile(){fields.value={};const values=tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(values.length>10||values.some(t=>t.length>24)||new Set(values).size!==values.length)fields.value.tags='最多10个不重复标签，每个不超过24字';if(!profile.value)return;if(Object.keys(fields.value).length)return;await mutate('/support/profiles/'+profile.value.uid,'PUT',{expected_revision:profile.value.revision,notes:notes.value,tags:values})}
async function createCase(){
 fields.value={};const n=integer(role.value,true)
 if(!profile.value)fields.value.target='先查找一个账号 UID，再为该账号建立问题记录'
 if(n===null)fields.value.role='角色编号须为正整数；账号级问题可留空'
 if(!title.value.trim())fields.value.title='请填写问题标题'
 if(!description.value.trim())fields.value.description='请填写问题描述'
 if(Object.keys(fields.value).length)return
 await mutate('/support/cases','POST',{uid:profile.value.uid,charac_no:n||null,title:title.value.trim(),category:newCategory.value,description:description.value.trim()})
 if(!pending.value&&!error.value){creating.value=false;title.value='';description.value='';role.value=''}
}
async function updateCase(){fields.value={};if(!edit.value.title.trim())fields.value.editTitle='请填写标题';if(!edit.value.description.trim())fields.value.editDescription='请填写描述';if(!edit.value.note.trim())fields.value.editNote='请说明本次修改或状态变化';if(Object.keys(fields.value).length)return;await mutate('/support/cases/'+current.value.case.case_id,'PUT',{...edit.value,expected_revision:editRevision.value})}
async function comment(){fields.value={};if(!entry.value.trim()){fields.value.entry='请填写处理记录';return}await mutate('/support/cases/'+current.value.case.case_id+'/entries','POST',{note:entry.value,expected_revision:current.value.case.revision});if(!pending.value&&!error.value)entry.value=''}
async function link(){fields.value={};if(!/^[a-f0-9]{32}$/.test(linkId.value.trim()))fields.value.linkId='请填写32位原操作编号';if(!linkNote.value.trim())fields.value.linkNote='请说明关联原因';if(Object.keys(fields.value).length)return;await mutate('/support/cases/'+current.value.case.case_id+'/links','POST',{operation_id:linkId.value.trim(),relation:relation.value,note:linkNote.value,expected_revision:current.value.case.revision});if(!pending.value&&!error.value){linkId.value='';linkNote.value=''}}
function compensate(kind:string){if(locked.value||!current.value||!canNavigate())return;emit('compensate',{...current.value.case,kind})}
function action(kind:string){if(!['detail','unlock'].includes(kind)&&!canNavigate())return;const c=current.value.case;emit('action',{action:kind,uid:c.uid,charac_no:c.charac_no||undefined})}
onMounted(async()=>{try{const id=sessionStorage.getItem(storage)||'';if(/^[A-Za-z0-9_-]{16,64}$/.test(id))pending.value=id}catch{};await load();if(pending.value)await recover()})
onBeforeUnmount(()=>{alive=false})
</script>
<template><section class="support-desk">
 <header class="section-title"><div><h2>玩家问题工作台</h2><p class="muted">备注、处理过程和原操作关联。建立问题或补偿草稿不会直接发奖。</p></div></header>
 <p v-if="error&&feedbackScope==='read'" class="submit-error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
 <div v-if="pending" class="notice"><b>保存结果待确认</b><p>请求编号：<code>{{pending}}</code>。只查询原编号，不重复创建；暂未查到记录也不代表一定未执行。</p><button :disabled="busy" @click="recover">查询原保存结果</button></div>
 <form class="support-filters" @submit.prevent="search"><label>账号 UID<input v-model="uidInput" inputmode="numeric" aria-label="工作台账号 UID" placeholder="留空查看全部" :disabled="busy"><small v-if="fields.uid" class="field-error">{{fields.uid}}</small></label><label>问题状态<select v-model="status" aria-label="筛选问题状态" :disabled="busy"><option value="">全部状态</option><option v-for="(label,id) in statuses" :key="id" :value="id">{{label}}</option></select></label><label>问题分类<select v-model="category" aria-label="筛选问题分类" :disabled="busy"><option value="">全部分类</option><option v-for="(label,id) in categories" :key="id" :value="id">{{label}}</option></select></label><label>标题／问题编号<input v-model="query" maxlength="100" aria-label="问题搜索" :disabled="busy"></label><button :disabled="busy">查询问题</button></form>
 <section v-if="profile" class="panel"><h3>{{profile.target.accountname}} · UID {{profile.uid}}</h3><form class="support-form" @submit.prevent="saveProfile"><label>账号备注<textarea v-model="notes" maxlength="4000" rows="3" aria-label="账号备注" :disabled="locked"/></label><label>标签（逗号分隔）<input v-model="tags" aria-label="玩家标签" :disabled="locked"><small v-if="fields.tags" class="field-error" role="alert">{{fields.tags}}</small></label><p v-if="error&&feedbackScope==='profile'" class="submit-error" role="alert">{{error}}</p><p v-if="profileDirty" class="field-hint">账号备注或标签尚未保存。<button type="button" :disabled="locked" @click="discardProfile">放弃备注修改</button></p><div class="button-row"><button :disabled="locked">保存账号备注与标签</button><button type="button" :disabled="locked" @click="creating=!creating">{{creating?'收起新问题':'建立问题记录'}}</button></div><small class="muted">版本 {{profile.revision}} · 不修改玩家密码、角色或游戏数据。</small></form></section>
 <p v-else class="field-hint">输入账号 UID 并查询，可维护备注和建立问题。也可以从“账号与角色”直接进入。</p>
 <form v-if="creating" class="panel support-form" @submit.prevent="createCase"><h3>新问题 · UID {{profile?.uid??'未选择'}}</h3><p v-if="fields.target" class="field-error" role="alert">{{fields.target}}</p><label>角色编号（可选）<input v-model="role" inputmode="numeric" aria-label="问题角色编号" :disabled="locked"><small v-if="fields.role" class="field-error" role="alert">{{fields.role}}</small></label><label>问题标题<input v-model="title" maxlength="120" aria-label="问题标题" :disabled="locked"><small v-if="fields.title" class="field-error" role="alert">{{fields.title}}</small></label><label>分类<select v-model="newCategory" aria-label="新问题分类" :disabled="locked"><option v-for="(label,id) in categories" :key="id" :value="id">{{label}}</option></select></label><label>问题描述<textarea v-model="description" maxlength="4000" rows="4" aria-label="问题描述" :disabled="locked"/><small v-if="fields.description" class="field-error" role="alert">{{fields.description}}</small></label><p v-if="error&&feedbackScope==='create'" class="submit-error" role="alert">{{error}}</p><button class="primary" :disabled="locked">保存新问题</button><button type="button" :disabled="locked" @click="title='';description='';role='';creating=false">取消新问题并清空草稿</button></form>
 <section class="panel"><h3>问题列表</h3><p v-if="!rows.length" class="empty">没有符合条件的问题记录</p><div class="support-cases"><button v-for="r in rows" :key="r.case_id" class="support-case" :disabled="busy" @click="open(r)"><span class="section-title"><b>{{r.title}}</b><span class="pill">{{statuses[r.status]}}</span></span><span>{{r.target.accountname}} · UID {{r.uid}}<span v-if="r.charac_no"> · {{r.target.character?.charac_name}} #{{r.charac_no}}</span></span><small>{{categories[r.category]}} · {{time(r.updated_at)}} · 已关联补偿 {{r.compensation_count}} 笔</small></button></div><div class="pagination"><button :disabled="busy||page<=1" @click="page--;load()">上一页问题</button><span>第 {{page}} 页</span><button :disabled="busy||!more" @click="page++;load()">下一页问题</button></div></section>
 <section v-if="current" class="panel support-detail" aria-label="问题详情"><div class="section-title"><h3>{{current.case.title}}</h3><span class="pill">{{statuses[current.case.status]}}</span></div><p>记录时目标：{{current.case.target.accountname}} · UID {{current.case.uid}}<span v-if="current.case.charac_no"> · {{current.case.target.character?.charac_name}} #{{current.case.charac_no}}</span></p><p class="muted">问题 #{{current.case.case_id}} · 版本 {{current.case.revision}}</p><p class="support-description">{{current.case.description}}</p>
 <p v-if="current.case.compensation_count" class="notice" role="status">此问题已关联 {{current.case.compensation_count}} 笔补偿，请先核对历史，避免重复补偿。数据库提交不等于玩家已领取或客户端生效。</p>
 <div class="button-row"><button :disabled="locked" @click="action('currency')">查看账号余额</button><button :disabled="locked||!current.case.charac_no" @click="action('detail')">查看角色资料</button><button :disabled="locked||!current.case.charac_no" @click="action('unlock')">排查装备解锁</button><button :disabled="locked" @click="action('support-mail')">查看玩家邮件</button><button :disabled="locked" @click="compensate('currency')">创建余额纠正草稿</button><button :disabled="locked" @click="compensate('mail')">创建邮件补偿草稿</button></div>
 <details><summary>编辑问题内容或处理状态</summary><form class="support-form" @submit.prevent="updateCase"><label>标题<input v-model="edit.title" maxlength="120" aria-label="修改问题标题" :disabled="locked"><small v-if="fields.editTitle" class="field-error" role="alert">{{fields.editTitle}}</small></label><label>分类<select v-model="edit.category" aria-label="修改问题分类" :disabled="locked"><option v-for="(label,id) in categories" :key="id" :value="id">{{label}}</option></select></label><label>描述<textarea v-model="edit.description" maxlength="4000" aria-label="修改问题描述" :disabled="locked"/><small v-if="fields.editDescription" class="field-error" role="alert">{{fields.editDescription}}</small></label><label>状态<select v-model="edit.status" aria-label="修改问题状态" :disabled="locked"><option v-for="(label,id) in statuses" :key="id" :value="id">{{label}}</option></select></label><label>处理说明<textarea v-model="edit.note" maxlength="2000" aria-label="状态修改说明" :disabled="locked"/><small v-if="fields.editNote" class="field-error" role="alert">{{fields.editNote}}</small></label><p v-if="error&&feedbackScope==='edit'" class="submit-error" role="alert">{{error}}</p><button :disabled="locked">保存问题修改</button></form></details>
 <form class="support-form" @submit.prevent="comment"><label>追加处理记录<textarea v-model="entry" maxlength="2000" rows="3" aria-label="处理记录" :disabled="locked"/><small v-if="fields.entry" class="field-error" role="alert">{{fields.entry}}</small></label><p v-if="error&&feedbackScope==='entry'" class="submit-error" role="alert">{{error}}</p><button :disabled="locked">追加处理记录</button></form>
 <details><summary>关联已有操作（不会重新执行）</summary><form class="support-form" @submit.prevent="link"><label>原操作编号<input v-model="linkId" maxlength="32" aria-label="关联操作编号" :disabled="locked"><small v-if="fields.linkId" class="field-error" role="alert">{{fields.linkId}}</small></label><label>关联用途<select v-model="relation" aria-label="操作关联用途" :disabled="locked"><option value="reference">排查参考，不计为补偿</option><option value="compensation">已完成的补偿</option></select></label><label>关联说明<textarea v-model="linkNote" maxlength="2000" aria-label="关联说明" :disabled="locked"/><small v-if="fields.linkNote" class="field-error" role="alert">{{fields.linkNote}}</small></label><p v-if="error&&feedbackScope==='link'" class="submit-error" role="alert">{{error}}</p><button :disabled="locked">关联原操作</button></form></details>
 <div v-if="detailDirty" class="notice"><p>当前问题有未保存草稿，刷新不会覆盖已编辑的内容。</p><p v-if="editDirty&&editRevision!==current.case.revision">问题版本已变化。保留的修改仍基于 v{{editRevision}}，提交不会覆盖新版；请复制需要保留的内容后放弃草稿，再重新编辑。</p><button :disabled="locked" @click="discardDetail">放弃当前问题草稿</button></div>
 <h4>关联操作</h4><p v-if="!current.links.length" class="empty">尚未关联操作</p><article v-for="l in current.links" :key="l.operation_id" class="support-entry"><span class="pill">{{l.relation==='compensation'?'补偿':'排查参考'}}</span><p>{{l.status?operationStatus(l):'原操作记录缺失，不能推断结果'}}</p><code>{{l.operation_id}}</code><button :disabled="busy" @click="emit('inspect',l.operation_id)">查询此原操作</button></article><div class="pagination"><button :disabled="busy||linkPage<=1" @click="linkPage--;detail(current.case.case_id)">上一页关联</button><span>第 {{linkPage}} 页</span><button :disabled="busy||!current.links_has_more" @click="linkPage++;detail(current.case.case_id)">下一页关联</button></div>
 <h4>处理时间线（不可删除）</h4><article v-for="e in current.events" :key="e.revision" class="support-entry"><div class="section-title"><b>{{kinds[e.kind]||e.kind}} · v{{e.revision}}</b><small>{{time(e.created_at)}}</small></div><p class="support-description">{{e.note}}</p><details v-if="Object.keys(e.details).length"><summary>查看变更与关联明细</summary><pre>{{JSON.stringify(e.details,null,2)}}</pre></details></article><div class="pagination"><button :disabled="busy||eventPage<=1" @click="eventPage--;detail(current.case.case_id)">上一页处理记录</button><span>第 {{eventPage}} 页</span><button :disabled="busy||!current.events_has_more" @click="eventPage++;detail(current.case.case_id)">下一页处理记录</button></div><button :disabled="busy" @click="detail(current.case.case_id)">刷新问题详情</button>
 </section><p v-if="busy" role="status">正在读取或保存管理记录…</p>
</section></template>
<style scoped>
.support-desk{display:grid;gap:20px}.support-desk h2,.support-desk h3{margin:0 0 12px}.support-filters{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.support-filters label{flex:1 1 160px;display:grid;gap:6px}.support-form{display:grid;gap:14px}.support-form label{display:grid;gap:6px}.support-form button{justify-self:start}.support-cases{display:grid;gap:10px}.support-case{display:grid;justify-content:stretch;align-items:stretch;text-align:left;gap:8px;width:100%;padding:16px;white-space:normal}.support-case small{font-weight:normal;color:var(--text-secondary)}.support-detail{min-width:0}.support-desk .button-row{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.support-desk code,.support-desk p{overflow-wrap:anywhere}.support-desk details{margin:14px 0}.support-desk summary{cursor:pointer;margin-bottom:12px}.support-description{white-space:pre-wrap}.support-entry{border-bottom:1px solid var(--border-color);padding:14px 0}.support-entry pre{white-space:pre-wrap;overflow-wrap:anywhere}.support-entry code{display:block;margin:10px 0}.support-desk textarea{min-height:90px;resize:vertical;width:100%;box-sizing:border-box}@media(max-width:600px){.support-desk .button-row>button{flex:1 1 140px}.support-form button{width:100%}.support-filters>button{width:100%}}
</style>
